use pulldown_cmark::*; use std::panic;
struct R(u64); impl R { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } fn b(&mut self,m:usize)->usize{(self.n()%(m as u64)) as usize} }
const T:&[&str]=&["a","b ","c d","\n","\n","\n\n","  ","    ","> ",">","- ","* ","1. ","# ","## ","---","===","```","~~~","\\","*","**","_","~","~~","$","$$","[","]","[[","]]","![","(",")","<",">","</a>","<a b='c'>","<a\nb='c'>","<!--","-->","<?","?>","|","|-|","| a |","\n|-|-|\n",":--",": ","[^a]","[^a]: ","[a]: /u","[a]:","\"t\"","'t'","&amp;","é","{#i .c}","[x] ","[!NOTE]","\\|","\\\n"];
fn evs(s:&str,o:Options)->Vec<Event<'static>>{ let mut v:Vec<Event<'static>>=vec![]; for e in TextMergeStream::new(Parser::new_ext(s,o)) { let e=match e { Event::Text(t)=>Event::Text(t.replace("\r\n","\n").into()), Event::Html(t)=>Event::Html(t.replace("\r\n","\n").into()), Event::InlineHtml(t)=>Event::InlineHtml(t.replace("\r\n","\n").into()), Event::InlineMath(t)=>Event::InlineMath(t.replace("\r\n","\n").into()), Event::DisplayMath(t)=>Event::DisplayMath(t.replace("\r\n","\n").into()), Event::Start(Tag::Link{link_type,dest_url,title,id})=>Event::Start(Tag::Link{link_type,dest_url:dest_url.into_static(),title:title.replace("\r\n","\n").into(),id:id.into_static()}), x=>x.into_static()}; if let (Some(Event::Html(a)),Event::Html(b))=(v.last(),&e){ let n=format!("{}{}",a,b); *v.last_mut().unwrap()=Event::Html(n.into()); continue;} v.push(e);} v }
fn bad(s:&str,o:Options)->bool{ let s1=s.to_string(); panic::catch_unwind(move||{ let c=s1.replace('\n',"\r\n"); evs(&s1,o)!=evs(&c,o)}).unwrap_or(false) }
fn main(){ panic::set_hook(Box::new(|_|{})); let mut r=R(777123456789); let mut seen=0; let start=std::time::Instant::now(); let mut sigs=std::collections::HashSet::new();
 while start.elapsed().as_secs()<100 && seen<40 { let l=1+r.b(14); let mut s=String::new(); for _ in 0..l { s.push_str(T[r.b(T.len())]); }
  let o=if r.b(2)==0 {Options::empty()} else {Options::ENABLE_TABLES|Options::ENABLE_FOOTNOTES|Options::ENABLE_STRIKETHROUGH|Options::ENABLE_MATH|Options::ENABLE_HEADING_ATTRIBUTES|Options::ENABLE_GFM};
  if bad(&s,o) { let mut cur:Vec<char>=s.chars().collect(); let mut ch=true; while ch { ch=false; let mut i=0; while i<cur.len(){ let mut t=cur.clone(); t.remove(i); let ts:String=t.iter().collect(); if bad(&ts,o){cur=t;ch=true;} else {i+=1;} } } let m:String=cur.iter().collect(); if sigs.insert(m.clone()) { seen+=1; let c=m.replace('\n',"\r\n"); println!("{:?} opts={:#x}\n  lf  {:?}\n  crlf {:?}",m,o.bits(),evs(&m,o),evs(&c,o)); } }
 } }
